mkuse!{use crate :: error :: Error ;}
mkuse!{use crate :: fmt ;}
mkitem!{mkstruct!{# [doc = " Errors which can occur when attempting to interpret a sequence of [`u8`]"] # [doc = " as a string."] # [doc = ""] # [doc = " As such, the `from_utf8` family of functions and methods for both [`String`]s"] # [doc = " and [`&str`]s make use of this error, for example."] # [doc = ""] # [doc = " [`String`]: ../../std/string/struct.String.html#method.from_utf8"] # [doc = " [`&str`]: super::from_utf8"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " This error type’s methods can be used to create functionality"] # [doc = " similar to `String::from_utf8_lossy` without allocating heap memory:"] # [doc = ""] # [doc = " ```"] # [doc = " fn from_utf8_lossy<F>(mut input: &[u8], mut push: F) where F: FnMut(&str) {"] # [doc = "     loop {"] # [doc = "         match std::str::from_utf8(input) {"] # [doc = "             Ok(valid) => {"] # [doc = "                 push(valid);"] # [doc = "                 break"] # [doc = "             }"] # [doc = "             Err(error) => {"] # [doc = "                 let (valid, after_valid) = input.split_at(error.valid_up_to());"] # [doc = "                 unsafe {"] # [doc = "                     push(std::str::from_utf8_unchecked(valid))"] # [doc = "                 }"] # [doc = "                 push(\"\\u{FFFD}\");"] # [doc = ""] # [doc = "                 if let Some(invalid_sequence_length) = error.error_len() {"] # [doc = "                     input = &after_valid[invalid_sequence_length..]"] # [doc = "                 } else {"] # [doc = "                     break"] # [doc = "                 }"] # [doc = "             }"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [derive (Copy , Eq , PartialEq , Clone , Debug)] # [stable (feature = "rust1" , since = "1.0.0")] pub struct Utf8Error { pub (super) valid_up_to : usize , pub (super) error_len : Option < u8 > , }}}
mkitem!{mkimpl!{impl Utf8Error { # [doc = " Returns the index in the given string up to which valid UTF-8 was"] # [doc = " verified."] # [doc = ""] # [doc = " It is the maximum index such that `from_utf8(&input[..index])`"] # [doc = " would return `Ok(_)`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Basic usage:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::str;"] # [doc = ""] # [doc = " // some invalid bytes, in a vector"] # [doc = " let sparkle_heart = vec![0, 159, 146, 150];"] # [doc = ""] # [doc = " // std::str::from_utf8 returns a Utf8Error"] # [doc = " let error = str::from_utf8(&sparkle_heart).unwrap_err();"] # [doc = ""] # [doc = " // the second byte is invalid here"] # [doc = " assert_eq!(1, error.valid_up_to());"] # [doc = " ```"] # [stable (feature = "utf8_error" , since = "1.5.0")] # [rustc_const_stable (feature = "const_str_from_utf8_shared" , since = "1.63.0")] # [must_use] # [inline] pub const fn valid_up_to (& self) -> usize { self . valid_up_to } # [doc = " Provides more information about the failure:"] # [doc = ""] # [doc = " * `None`: the end of the input was reached unexpectedly."] # [doc = "   `self.valid_up_to()` is 1 to 3 bytes from the end of the input."] # [doc = "   If a byte stream (such as a file or a network socket) is being decoded incrementally,"] # [doc = "   this could be a valid `char` whose UTF-8 byte sequence is spanning multiple chunks."] # [doc = ""] # [doc = " * `Some(len)`: an unexpected byte was encountered."] # [doc = "   The length provided is that of the invalid byte sequence"] # [doc = "   that starts at the index given by `valid_up_to()`."] # [doc = "   Decoding should resume after that sequence"] # [doc = "   (after inserting a [`U+FFFD REPLACEMENT CHARACTER`][U+FFFD]) in case of"] # [doc = "   lossy decoding."] # [doc = ""] # [doc = " [U+FFFD]: ../../std/char/constant.REPLACEMENT_CHARACTER.html"] # [stable (feature = "utf8_error_error_len" , since = "1.20.0")] # [rustc_const_stable (feature = "const_str_from_utf8_shared" , since = "1.63.0")] # [must_use] # [inline] pub const fn error_len (& self) -> Option < usize > { match self . error_len { Some (len) => Some (len as usize) , None => None , } } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl fmt :: Display for Utf8Error { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { if let Some (error_len) = self . error_len { write ! (f , "invalid utf-8 sequence of {} bytes from index {}" , error_len , self . valid_up_to) } else { write ! (f , "incomplete utf-8 byte sequence from index {}" , self . valid_up_to) } } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl Error for Utf8Error { }}}
mkitem!{mkstruct!{# [doc = " An error returned when parsing a `bool` using [`from_str`] fails"] # [doc = ""] # [doc = " [`from_str`]: super::FromStr::from_str"] # [derive (Debug , Clone , PartialEq , Eq)] # [non_exhaustive] # [stable (feature = "rust1" , since = "1.0.0")] pub struct ParseBoolError ;}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl fmt :: Display for ParseBoolError { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { "provided string was not `true` or `false`" . fmt (f) } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl Error for ParseBoolError { }}}